/* FIN TAX PRO – CashBook service worker (generated by scripts/build-sw.mjs). */
/* eslint-disable no-restricted-globals */
const VERSION = '__SW_VERSION__'
const SHELL = `shell-${VERSION}`
const STATIC = 'static-v1' // hashed Next.js assets are immutable, safe to keep across versions
const CORE = ['/', '/login', '/dashboard', '/manifest.webmanifest', '/icons/icon-192.png', '/icons/icon-512.png', '/favicon.png']

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(SHELL).then((c) => c.addAll(CORE)).catch(() => {}))
  // Do NOT skipWaiting automatically: the page asks the user first so an
  // unsaved form is never reloaded away.
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys()
      await Promise.all(keys.filter((k) => k.startsWith('shell-') && k !== SHELL).map((k) => caches.delete(k)))
      await self.clients.claim()
    })(),
  )
})

self.addEventListener('message', (event) => {
  const msg = event.data || {}
  if (msg.type === 'SKIP_WAITING') self.skipWaiting()
  if (msg.type === 'WARM' && Array.isArray(msg.routes)) event.waitUntil(warm(msg.routes))
})

/** Cache every app screen and the JS/CSS it needs so the app opens fully offline. */
async function warm(routes) {
  const shell = await caches.open(SHELL)
  const stat = await caches.open(STATIC)
  const assets = new Set()
  for (const route of routes) {
    try {
      const res = await fetch(route, { credentials: 'same-origin', cache: 'no-cache' })
      if (!res.ok || !(res.headers.get('content-type') || '').includes('text/html')) continue
      const html = await res.clone().text()
      await shell.put(route, res)
      for (const m of html.matchAll(/["'(](\/_next\/static\/[^"')\s]+)/g)) assets.add(m[1].replace(/\\u0026/g, '&'))
    } catch {
      /* offline – try again next time */
    }
  }
  for (const url of assets) {
    if (await stat.match(url)) continue
    try {
      const res = await fetch(url)
      if (res.ok) await stat.put(url, res)
    } catch {
      /* ignore */
    }
  }
}

function timeout(ms) {
  return new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms))
}

self.addEventListener('fetch', (event) => {
  const req = event.request
  if (req.method !== 'GET') return
  const url = new URL(req.url)
  // Never touch API / auth / storage traffic (Supabase is cross-origin).
  if (url.origin !== self.location.origin) return

  // React Server Component payloads: when offline, fail fast so the router
  // falls back to a full page load, which is served from the cache below.
  if (req.headers.get('RSC') === '1' || url.searchParams.has('_rsc')) {
    event.respondWith(fetch(req).catch(() => Response.error()))
    return
  }

  if (url.pathname.startsWith('/_next/static/')) {
    event.respondWith(
      caches.open(STATIC).then(async (c) => {
        const hit = await c.match(req)
        if (hit) return hit
        const res = await fetch(req)
        if (res.ok) c.put(req, res.clone())
        return res
      }),
    )
    return
  }

  if (req.mode === 'navigate') {
    event.respondWith(
      (async () => {
        const shell = await caches.open(SHELL)
        try {
          const res = await Promise.race([fetch(req), timeout(5000)])
          if (res.ok) shell.put(url.pathname, res.clone())
          return res
        } catch {
          return (
            (await shell.match(url.pathname)) ||
            (await shell.match(req, { ignoreSearch: true })) ||
            (await shell.match('/dashboard')) ||
            new Response('<h1>Offline</h1><p>Open the app once while online to enable offline use.</p>', { headers: { 'Content-Type': 'text/html' } })
          )
        }
      })(),
    )
    return
  }

  // Icons, manifest and other public files: stale-while-revalidate.
  event.respondWith(
    caches.open(SHELL).then(async (c) => {
      const hit = await c.match(req)
      const net = fetch(req)
        .then((res) => {
          if (res.ok && res.type === 'basic') c.put(req, res.clone())
          return res
        })
        .catch(() => hit)
      return hit || net
    }),
  )
})
